// it reaches 100% (see isLocaleReady in i18n.ts) so nobody lands on a page that
// switches between two languages mid-scroll.
// Re-run after changing dictionaries or UI strings:  pnpm gen:locale-readiness

export interface LocaleReadiness {
  /** Percent of scored UI strings that are genuinely in this language. */
  dict: number;
  /** Percent of the site's own writing translated and cached for this language. */
  content: number;
  /** The lower of the two — a language is only as finished as its weakest half. */
  overall: number;
  /** Up to 40 English strings still showing through, for the admin portal. */
  missing: string[];
}

